import{_ as t,o as a,c as s,a4 as o}from"./chunks/framework.CcIOJJza.js";const n="/mxcad/assets/image-20260208151451501.D8uT-aXL.png",r="/mxcad/assets/image-20260208140709479.BLN1yr6k.png",i="/mxcad/assets/image-20260208152035424.DU5P-1si.png",c="/mxcad/assets/image-20260208152258922.BaqxI-UT.png",p="/mxcad/assets/image-20260208153035849.BGoLxLiG.png",d="/mxcad/assets/image-20260208153446491.DOjYJdBY.png",l="/mxcad/assets/image-20260208154049671.DumdYAYK.png",u="/mxcad/assets/image-20260208154319593.CV7CWokb.png",g="/mxcad/assets/image-20260208154755674.BgMOCtYr.png",h="/mxcad/assets/image-20260208155242020.CKe-dHbk.png",m="/mxcad/assets/image-20260208155534255.ihAhwROK.png",v="/mxcad/assets/image-20260208155609893.D5JegiVr.png",f="/mxcad/assets/image-20260208155640120.msBDNZva.png",b="/mxcad/assets/image-20260208155902316.CzZQf1LG.png",w="/mxcad/assets/image-20260208160507097.CeplLI7Z.png",D="/mxcad/assets/image-20260208160234626.DqB818SV.png",x="/mxcad/assets/image-20260208160647592.DMuTr9a4.png",y="/mxcad/assets/image-20260208160810176.C-22584s.png",P=JSON.parse('{"title":"MxDraw Cloud Drawing Development Kit Structure and Function Description (Essential for Beginners)","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/8.RelatedArticles/1.IntroductionGuide/2.Cloud Map Development Kit Instructions.md","filePath":"en/docs/8.RelatedArticles/1.IntroductionGuide/2.Cloud Map Development Kit Instructions.md"}'),C={name:"en/docs/8.RelatedArticles/1.IntroductionGuide/2.Cloud Map Development Kit Instructions.md"};function k(_,e,S,A,q,M){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="mxdraw-cloud-drawing-development-kit-structure-and-function-description-essential-for-beginners" tabindex="-1">MxDraw Cloud Drawing Development Kit Structure and Function Description (Essential for Beginners) <a class="header-anchor" href="#mxdraw-cloud-drawing-development-kit-structure-and-function-description-essential-for-beginners" aria-label="Permalink to &quot;MxDraw Cloud Drawing Development Kit Structure and Function Description (Essential for Beginners)&quot;">​</a></h1><h2 id="_1-what-is-the-mxdraw-cloud-drawing-development-kit" tabindex="-1">1. What is the MxDraw Cloud Drawing Development Kit <a class="header-anchor" href="#_1-what-is-the-mxdraw-cloud-drawing-development-kit" aria-label="Permalink to &quot;1. What is the MxDraw Cloud Drawing Development Kit&quot;">​</a></h2><p>The Cloud Drawing Development Kit is a <strong>complete set of engineering collections for CAD cloudification solutions built around MxCAD</strong>. It is not a single SDK, but a package of projects that unifies <strong>background drawing conversion, service interfaces, front-end project examples, and MxCAD editing &amp; browsing capabilities</strong>. For beginners, it can be understood this way: the Cloud Drawing Development Kit has already split a &quot;CAD cloud system&quot; into corresponding directories for you.</p><p><strong>Note</strong>: The Cloud Drawing Development Kit provides corresponding versions for different operating systems (such as Windows, Linux, etc.), and the executable program form, deployment method and startup method of the development kit may vary. However, regardless of the operating system it runs on, the Cloud Drawing Development Kit remains consistent in terms of functions and overall architecture design. The directory responsibilities, core capabilities and usage methods are not affected by the platform, and the architecture and descriptions in this document apply to all operating system versions.</p><h2 id="_2-overview-of-the-overall-directory-structure" tabindex="-1">2. Overview of the Overall Directory Structure <a class="header-anchor" href="#_2-overview-of-the-overall-directory-structure" aria-label="Permalink to &quot;2. Overview of the Overall Directory Structure&quot;">​</a></h2><p>The root directory of the MxDraw Cloud Drawing Development Kit is:</p><p>Windows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MXDRAWCLOUDSERVER1.0_XXX_TRYVERSION （where XXX is the version number of the Cloud Drawing Development Kit）</span></span>
<span class="line"><span>└─ MxDrawCloudServer   （Root directory of the Cloud Drawing Development Kit</span></span></code></pre></div><p><img src="`+n+`" alt="image-20260208151451501"></p><p>Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MXDRAWCLOUDSERVER1.0_XXX_xxx_TRYVERSION （where XXX is the version number of the Cloud Drawing Development Kit, xxx is the corresponding operating system）</span></span>
<span class="line"><span>└─ install</span></span>
<span class="line"><span>   └─ MxDrawCloudServer   （Root directory of the Cloud Drawing Development Kit）</span></span></code></pre></div><p><img src="`+r+`" alt="image-20260208140709479"> From a functional perspective, the directories can be divided into three main parts:</p><ol><li><p><strong>Bin: Background Services and Core Capabilities</strong></p></li><li><p><strong>SRC: Front-end Projects and Sample Source Code</strong></p></li><li><p><strong>Mx3dServer.exe: Start services and demo pages (Windows)</strong></p><p><strong>start_demo.sh: Start services and demo pages (Linux)</strong></p></li></ol><p>For beginners to understand the Cloud Drawing Development Kit, as long as you first understand the division of labor of these three parts, you won&#39;t get lost.</p><h2 id="_3-bin-directory-background-service-related-directory-core" tabindex="-1">3. Bin Directory: Background Service-related Directory (Core) <a class="header-anchor" href="#_3-bin-directory-background-service-related-directory-core" aria-label="Permalink to &quot;3. Bin Directory: Background Service-related Directory (Core)&quot;">​</a></h2><p>Windows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ Bin</span></span>
<span class="line"><span>   └─ MxCAD   （Drawing conversion program directory）</span></span>
<span class="line"><span>   └─ MxDrawServer   （Background service directory of the MxCAD project）</span></span></code></pre></div><p><img src="`+i+`" alt="image-20260208152035424"> Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ Bin</span></span>
<span class="line"><span>   └─ Linux   </span></span>
<span class="line"><span>       └─ MxCAD   （Drawing conversion program directory）</span></span>
<span class="line"><span>       └─ MxDrawServer   （Background service directory of the MxCAD project）</span></span></code></pre></div><p><img src="`+c+`" alt="image-20260208152258922"> <strong>Bin is the core directory in the Cloud Drawing Development Kit</strong>, which bears the necessary background capabilities for CAD cloudification.</p><h3 id="_1-mxcad-——-drawing-conversion-program-directory" tabindex="-1">1. MxCAD —— Drawing Conversion Program Directory <a class="header-anchor" href="#_1-mxcad-——-drawing-conversion-program-directory" aria-label="Permalink to &quot;1. MxCAD —— Drawing Conversion Program Directory&quot;">​</a></h3><ul><li>Used for <strong>conversion and processing of CAD drawings</strong></li><li>Converts the format of original drawings such as DWG / DXF</li><li>Is a prerequisite for the cloud drawing system to &quot;display CAD online&quot;</li></ul><p>Without the corresponding conversion program in this directory, the front end cannot directly display and edit CAD drawings.</p><h3 id="_2-mxdrawserver-——-background-service-directory-of-the-mxcad-project" tabindex="-1">2. MxDrawServer —— Background Service Directory of the MxCAD Project <a class="header-anchor" href="#_2-mxdrawserver-——-background-service-directory-of-the-mxcad-project" aria-label="Permalink to &quot;2. MxDrawServer —— Background Service Directory of the MxCAD Project&quot;">​</a></h3><ul><li><p>Provides <strong>background interface services required within the MxCAD project</strong></p></li><li><p>Offers service support for CAD drawing loading, processing, interaction and other capabilities</p></li><li><p>Is part of the <strong>MxCAD engineering system</strong></p></li></ul><p>This is a key background module connecting &quot;drawing data&quot; and &quot;CAD functions&quot;.</p><h2 id="_4-src-directory-front-end-project-related-directory" tabindex="-1">4. SRC Directory: Front-end Project-related Directory <a class="header-anchor" href="#_4-src-directory-front-end-project-related-directory" aria-label="Permalink to &quot;4. SRC Directory: Front-end Project-related Directory&quot;">​</a></h2><p>Windows/Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ SRC</span></span>
<span class="line"><span>   └─ sample   （Front-end project sample code directory）</span></span>
<span class="line"><span>   └─ TsWeb   （Web front-end portal of cloud services）</span></span>
<span class="line"><span>   └─ doc   （Document directory）</span></span></code></pre></div><p><img src="`+p+`" alt="image-20260208153035849"> The SRC directory is a core area for developers in the MxDraw Cloud Drawing Development Kit, containing all openable front-end sample project source codes, integration templates and supporting documents. Whether you want to quickly experience the functions or conduct in-depth secondary development, you should start with this directory.</p><h3 id="_1-doc-——-document-directory-empty-folder-by-default" tabindex="-1">1. doc —— Document Directory (empty folder by default) <a class="header-anchor" href="#_1-doc-——-document-directory-empty-folder-by-default" aria-label="Permalink to &quot;1. doc —— Document Directory (empty folder by default)&quot;">​</a></h3><ul><li>Stores instruction documents, API manuals or integration guides related to front-end projects.</li><li>Developers can supplement custom instructions here to assist team collaboration or project handover.</li></ul><h3 id="_2-tsweb——-web-service-and-frontend-resource-hosting-module" tabindex="-1"><strong>2.</strong> TsWeb—— Web Service and Frontend Resource Hosting Module <a class="header-anchor" href="#_2-tsweb——-web-service-and-frontend-resource-hosting-module" aria-label="Permalink to &quot;**2.** TsWeb—— Web Service and Frontend Resource Hosting Module&quot;">​</a></h3><p>The TsWeb directory is a core component of the MxDraw Cloud Drawing SDK, responsible for <strong>hosting web frontend services and acting as an API proxy</strong>. Built on Node.js and the Express framework, it does not perform CAD graphics computations. Instead, it serves as a &quot;bridge&quot; between the user&#39;s browser and the backend CAD engine, providing capabilities such as page loading, resource distribution, and lightweight API forwarding.</p><h3 id="_3-sample-——-front-end-project-sample-code-directory-key" tabindex="-1">3. sample —— Front-end Project Sample Code Directory (Key) <a class="header-anchor" href="#_3-sample-——-front-end-project-sample-code-directory-key" aria-label="Permalink to &quot;3. sample —— Front-end Project Sample Code Directory (Key)&quot;">​</a></h3><p>Windows/Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ SRC</span></span>
<span class="line"><span>   └─ app   （Integration examples of mxcad-app in projects with different architectures）</span></span>
<span class="line"><span>   └─ Edit   （Source code directory of the CAD editing version project）</span></span></code></pre></div><p><img src="`+d+`" alt="image-20260208153446491"> This directory provides complete front-end engineering examples for various typical application scenarios, covering core capabilities such as browsing, editing, 3D, GIS, etc., and is the best entry point for beginners to learn and reference projects.</p><h4 id="_1-app-——-source-code-of-cad-editing-project-examples-integrating-the-mxcad-app-dependency-package" tabindex="-1">(1) app —— Source code of CAD editing project examples integrating the mxcad-app dependency package <a class="header-anchor" href="#_1-app-——-source-code-of-cad-editing-project-examples-integrating-the-mxcad-app-dependency-package" aria-label="Permalink to &quot;(1) app —— Source code of CAD editing project examples integrating the mxcad-app dependency package&quot;">​</a></h4><p>Windows/Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ SRC</span></span>
<span class="line"><span>   └─ sample   （Front-end project sample code directory） </span></span>
<span class="line"><span>       └─ app   （Source code of integration examples of mxcad-app in projects with different architectures）</span></span>
<span class="line"><span>          └─ MxCADApp   （Vue2+Webpack）</span></span>
<span class="line"><span>          └─ plugins   （Project plugin directory）</span></span>
<span class="line"><span>             └─ pluginAiChat   （AI module）</span></span>
<span class="line"><span>          └─ sample</span></span>
<span class="line"><span>             └─ webapack4 </span></span>
<span class="line"><span>             └─ html+js</span></span>
<span class="line"><span>             └─ vite+vue3</span></span>
<span class="line"><span>             └─ webapck+react</span></span>
<span class="line"><span>             └─ cnd.html</span></span></code></pre></div><p><img src="`+l+`" alt="image-20260208154049671"> Provides standard ways to integrate <code>mxcad-app</code> under different front-end technology stacks:</p><ul><li><p><code>MxCADApp</code>: A complete editor project based on Vue2 + Webpack</p></li><li><p><code>plugins</code>: Built-in plugin extension mechanism, such as <code>pluginAiChat</code> (AI chat module)</p></li><li><p>Multi-framework adaptation examples: Including <code>vite+vue3</code>, <code>webpack+react</code>, <code>html+js</code> and CDN introduction method (<code>cnd.html</code>)</p></li></ul><h4 id="_2-browse-——-source-code-directory-of-the-cad-browsing-version-project" tabindex="-1">(2) Browse —— Source code directory of the CAD browsing version project <a class="header-anchor" href="#_2-browse-——-source-code-directory-of-the-cad-browsing-version-project" aria-label="Permalink to &quot;(2) Browse —— Source code directory of the CAD browsing version project&quot;">​</a></h4><p>Windows/Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ SRC</span></span>
<span class="line"><span>   └─ sample   （Front-end project sample code directory） </span></span>
<span class="line"><span>      └─ Browse   （CAD browsing version project example）</span></span>
<span class="line"><span>          └─ 2d </span></span>
<span class="line"><span>             └─ Browseiframe   （iframe nested integration example）</span></span>
<span class="line"><span>             └─ Browse   （Source code directory of the CAD browsing version project）</span></span></code></pre></div><p><img src="`+u+`" alt="image-20260208154319593"> Focuses on drawing viewing scenarios and supports lightweight deployment:</p><ul><li><p><code>2d/Browse</code>: Pure 2D drawing browsing page</p></li><li><p><code>2d/Browseiframe</code>: Browsing mode integrated through <code>iframe</code> nesting, easy to embed into third-party systems</p></li></ul><h4 id="_3-edit——-source-code-directory-of-the-cad-editing-version-project" tabindex="-1">(3) Edit—— Source code directory of the CAD editing version project <a class="header-anchor" href="#_3-edit——-source-code-directory-of-the-cad-editing-version-project" aria-label="Permalink to &quot;(3) Edit—— Source code directory of the CAD editing version project&quot;">​</a></h4><p>Windows/Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxDrawCloudServer</span></span>
<span class="line"><span>└─ SRC</span></span>
<span class="line"><span>   └─ sample   （Front-end project sample code directory） </span></span>
<span class="line"><span>      └─ Edit   （CAD editing version project example）</span></span>
<span class="line"><span>          └─ 2d  （2D drawing project）</span></span>
<span class="line"><span>             └─ dist   （Static resource package of MxCAD APP）</span></span>
<span class="line"><span>             └─ MxCAD   （Source code directory of a plugin in MxCAD APP）</span></span>
<span class="line"><span>             └─ MxCADiframe   （iframe nested integration example）</span></span></code></pre></div><p><img src="`+g+'" alt="image-20260208154755674"> Provides complete online editing capabilities:</p><ul><li><code>Edit/2d</code>: 2D drawing editing environment, including toolbar, property panel, etc.</li><li><code>dist</code> subdirectory: Precompiled static resource package, which can be directly deployed to web servers</li></ul><h2 id="_5-mx3dserver-exe-start-demo-sh-mxdraw-cloud-drawing-startup-entry" tabindex="-1">5. Mx3dServer.exe/start_demo.sh: Mxdraw Cloud Drawing Startup Entry <a class="header-anchor" href="#_5-mx3dserver-exe-start-demo-sh-mxdraw-cloud-drawing-startup-entry" aria-label="Permalink to &quot;5. Mx3dServer.exe/start_demo.sh: Mxdraw Cloud Drawing Startup Entry&quot;">​</a></h2><p><code>Mx3dServer.exe</code> (Windows) and <code>start_demo.sh</code> (Linux) are the <strong>unified startup entries</strong> of the MxDraw Cloud Drawing Development Kit, used to initialize the entire CAD cloud service environment with one click. They shield complex details such as background service configuration, port binding, and dependency startup, allowing developers or users to enter the demo state only by &quot;double-clicking&quot; or &quot;executing the script&quot;.</p><h3 id="_1-mx3dserver-exe-dream-cloud-drawing-service-startup-program-graphical-entry" tabindex="-1">1. <strong>Mx3dServer.exe: Dream Cloud Drawing Service Startup Program (Graphical Entry)</strong> <a class="header-anchor" href="#_1-mx3dserver-exe-dream-cloud-drawing-service-startup-program-graphical-entry" aria-label="Permalink to &quot;1. **Mx3dServer.exe: Dream Cloud Drawing Service Startup Program (Graphical Entry)**&quot;">​</a></h3><p><code>Mx3dServer.exe</code> is the <strong>graphical startup program</strong> of the MxDraw Cloud Drawing Development Kit on the Windows platform. Double-clicking to run it will automatically pop up the &quot;Dream Cloud Drawing Service Startup Program&quot; window. This program integrates the unified management and quick access functions of multi-module services, which greatly simplifies the deployment process, allowing developers and users to start a complete online CAD demo environment with one click without manual configuration. <img src="'+h+'" alt="image-20260208155242020"></p><ul><li><p><strong>Start Web Service</strong>:</p><p>When you click the <strong>&quot;Start Web Service&quot;</strong></p><p>button, MxDraw will automatically start two key local service programs. These two services work together to support a complete online CAD function experience.</p><p><img src="'+m+'" alt="image-20260208155534255"></p></li><li><p><strong>First Service (Port 1337): CAD Core Engine</strong></p><p>This service is started by the <code>Bin/MxDrawServer/Windows/app.js</code> script and is the &quot;brain&quot; of MxDraw. It is responsible for processing all underlying operations related to drawings, such as opening DWG files, parsing graphic data, saving editing results, etc. Although you cannot see its interface, all CAD functions rely on it to complete. <img src="'+v+'" alt="image-20260208155609893"></p></li><li><p><strong>Second Service (Port 3000): Web Front-end Server</strong></p><p>This service is started by the <code>SRC/TsWeb/app.js</code> script and is the user&#39;s &quot;operation window&quot;. It is built based on the Express framework and is responsible for hosting all web files (such as 2D editor, 3D viewer, file browser, etc.), and forwarding your operation requests to the CAD engine. The interfaces, buttons, and toolbars you see are all provided by this service. <img src="'+f+'" alt="image-20260208155640120"></p></li><li><p><strong>Start MxCAD</strong></p><p>Open the 2D CAD online editor, which supports complete editing functions such as drawing, modification, annotation, upload, and save, suitable for engineering design scenarios.</p><p><img src="'+b+'" alt="image-20260208155902316"></p></li><li><p><strong>NodeJs Service Test</strong></p><p>Open the <code>http://localhost:1337/serverTest</code> page, which provides a visual test function for one-click calling core CAD interfaces such as DWG conversion, PDF export, and layer reading. <img src="'+w+'" alt="image-20260208160507097"></p></li></ul><ul><li><p><strong>Convert DWG to Dream File Format</strong></p><p>Start the DWG format conversion tool to batch convert standard AutoCAD DWG files to MxDraw&#39;s proprietary <code>.mxweb</code> format, improving loading speed and compatibility.</p><p><img src="'+D+'" alt="image-20260208160234626"></p></li><li><p><strong>About</strong></p><p>Displays software version number and copyright information. <img src="'+x+'" alt="image-20260208160647592"></p></li><li><p><strong>Exit</strong></p><p>Close the startup program window.</p><blockquote><p>Tip: When running for the first time, please allow the network access permission of <code>Mx3dServer.exe</code> in the Windows Firewall to ensure the service can be connected normally. It is recommended to use the latest version of Chrome or Edge browser for the best experience.</p></blockquote></li></ul><h3 id="_2-start-demo-sh-cloud-drawing-service-startup-script-for-linux-platform" tabindex="-1">2. start_demo.sh: <strong>Cloud Drawing Service Startup Script for Linux Platform</strong> <a class="header-anchor" href="#_2-start-demo-sh-cloud-drawing-service-startup-script-for-linux-platform" aria-label="Permalink to &quot;2. start_demo.sh: **Cloud Drawing Service Startup Script for Linux Platform**&quot;">​</a></h3><p><code>start_demo.sh</code> is the <strong>standard startup script</strong> of the MxDraw Cloud Drawing Development Kit on the <strong>Linux system</strong>, used to initialize a complete Web CAD demo environment with one click. Its functions are completely equivalent to <code>Mx3dServer.exe</code> on the Windows platform, ensuring a consistent cross-platform experience.</p><h3 id="core-functions" tabindex="-1"><strong>Core Functions</strong> <a class="header-anchor" href="#core-functions" aria-label="Permalink to &quot;**Core Functions**&quot;">​</a></h3><ul><li>Start two key services at the same time: <ul><li>CAD Core Service** (Node.js): Runs on port <code>1337</code>, providing underlying capabilities such as DWG parsing, drawing command execution, and format conversion;</li><li><strong>Web Front-end Service</strong> (Express): Runs on port <code>3000</code>, hosting all demo pages (such as 2D editor, 3D viewer, file browser, etc.).</li></ul></li><li>Automatically configure service paths and dependencies without manually executing multiple commands.</li></ul><h3 id="usage-steps" tabindex="-1"><strong>Usage Steps</strong> <a class="header-anchor" href="#usage-steps" aria-label="Permalink to &quot;**Usage Steps**&quot;">​</a></h3><ol><li><p><strong>Check the LinuxDemo Startup Instructions in Advance</strong></p><p>Refer to &quot;LinuxDemo Startup Instructions.txt&quot; to set permissions and run.</p><p><img src="'+y+'" alt="image-20260208160810176"></p></li><li><p><strong>Execute the Startup Script</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>./start_demo.sh</span></span></code></pre></div></li><li><p><strong>Access the Demo Page</strong></p><p>After the service starts successfully, open the following in the browser:</p><ul><li>Home page: <code>http://localhost:3000</code></li><li>2D Editing: <code>http://localhost:3000/mxcad</code></li></ul></li></ol><h3 id="notes" tabindex="-1"><strong>Notes</strong> <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;**Notes**&quot;">​</a></h3><ul><li><p>The script starts the service in the background by default. If debugging is needed, modify the script to remove the <code>&amp;</code> symbol to view real-time logs;</p></li><li><p>If the port is occupied, the <code>PORT</code> variable in the script can be edited to adjust;</p><blockquote><p><strong>Tip</strong>: Although there is no graphical interface, <code>start_demo.sh</code> provides the same functional integrity as the Windows <code>.exe</code> file, and is a standard entry point for Linux developers to quickly verify and integrate MxDraw cloud drawing capabilities.</p></blockquote></li></ul>',67)]))}const W=t(C,[["render",k]]);export{P as __pageData,W as default};
